#if UNITY_EDITOR
using LastRail.Battle;
using NUnit.Framework;
using System;
using System.IO;
using Newtonsoft.Json.Linq;
namespace LastRail.Tests.EditMode {
 public sealed class RunEquipmentStatSourceTests {
  const string Qa="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/RunEquipmentSource-20261005/";
  static JObject Sample()=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/equipment-run-stat-owner-sql-sample-20261005.json"))["proposedStatSnapshot"];
  static JObject Produced() => JObject.Parse(File.ReadAllText(Qa+"original-producer-samples.json"));
  static RunEquipmentStatSource Read(JObject p=null){p=p??Sample();return RunEquipmentStatSource.Read(p,p,(string)p["packetHash"],(string)p["accountId"],(string)p["runId"],(string)p["originalContextHash"],(long)p["inventoryRevision"]);}
  static void Rehash(JObject p){p.Remove("packetHash");p["packetHash"]=BDirectAttackInput.Digest(p).Substring(7);}
  [Test] public void ProposedEquipmentSourceHasExplicitConsumerBoundary(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Battle.RunEquipmentStatSource"),"Proposed internal equipment source needs its own immutable boundary; not committed native stats");}
  [Test] public void OriginalSqlSamplePreservesExactStatsBaseAndPrecommitPhase(){var p=Sample();var s=Read(p);Assert.IsTrue(JToken.DeepEquals(p,s.Capture()));Assert.AreEqual("e150daf82931375a83222a06be5a0e1fa7f8ea969da0e00564fb2ca7123b60b5",s.Hash);var a=s.ActorProposal("operator","op_kyle");Assert.AreEqual(1624,(int)a["stats"]["maxHp"]);Assert.AreEqual("36",(string)a["stats"]["attack"]["numerator"]);Assert.AreEqual("250",(string)a["stats"]["defense"]["numerator"]);Assert.AreEqual("3600000000",(string)a["base"]["attack"]["numerator"]);Assert.AreEqual(RunEquipmentStatSource.ProposedPhase,(string)s.Capture()["phase"]);Assert.IsFalse(s.CanApplyToNative);}
  [Test] public void MutableCallerInputAndReturnedProjectionsCannotChangeCapturedSource(){var p=Sample();var s=Read(p);p["actors"][0]["stats"]["maxHp"]=1;s.Capture()["actors"][0]["slots"][0]["setTag"]="SET01";s.ActorProposal("operator","op_kyle")["stats"]["maxHp"]=2;Assert.AreEqual(1624,(int)s.ActorProposal("operator","op_kyle")["stats"]["maxHp"]);Assert.AreEqual("SET04",(string)s.Capture()["actors"][0]["slots"][0]["setTag"]);}
  [TestCase("threeSlots")][TestCase("twoWearers")][TestCase("twoStar")]
  public void ActualOriginalProducerOneAndTwoStarSourcesRemainProposals(string kind){var p=(JObject)Produced()[kind];var s=Read(p);Assert.IsTrue(JToken.DeepEquals(p,s.Capture()));Assert.IsFalse(s.CanApplyToNative);var a=s.ActorProposal("operator","op_kyle");if(kind=="threeSlots"){Assert.AreEqual(1764,(int)a["stats"]["maxHp"]);Assert.AreEqual("1026",(string)a["stats"]["attack"]["numerator"]);Assert.AreEqual("25",(string)a["stats"]["attack"]["denominator"]);Assert.AreEqual("275",(string)a["stats"]["defense"]["numerator"]);Assert.AreEqual(3,((JArray)a["slots"]).Count);}else if(kind=="twoStar"){Assert.AreEqual(1834,(int)a["stats"]["maxHp"]);Assert.AreEqual(2,(int)a["slots"][0]["star"]);Assert.AreEqual(2,(int)a["sources"][0]["effectRevision"]);Assert.AreEqual(2,(int)a["sources"][0]["instanceRevision"]);}else{Assert.AreEqual(1624,(int)a["stats"]["maxHp"]);var sable=s.ActorProposal("operator","op_sable");Assert.AreEqual(1600,(int)sable["stats"]["maxHp"]);Assert.AreEqual("912",(string)sable["stats"]["attack"]["numerator"]);Assert.AreEqual("25",(string)sable["stats"]["attack"]["denominator"]);Assert.AreEqual(0,(int)sable["stats"]["additiveBps"]["HP"]);}}
  [TestCase("account")][TestCase("run")][TestCase("context")][TestCase("revision")]
  public void IndependentOwnerRunContextAndInventoryPinsAreRequired(string fault){var p=Sample();Assert.Throws<ArgumentException>(()=>RunEquipmentStatSource.Read(p,p,(string)p["packetHash"],fault=="account"?"foreign":(string)p["accountId"],fault=="run"?"other-run":(string)p["runId"],fault=="context"?new string('0',64):(string)p["originalContextHash"],fault=="revision"?2:1));}
  [TestCase("stats")][TestCase("base")][TestCase("target")][TestCase("instanceRevision")][TestCase("effectRevision")][TestCase("tag")][TestCase("phase")]
  public void RehashedCallerMutationCannotReplacePinnedOriginal(string fault){var original=Sample();var p=(JObject)original.DeepClone();var a=p["actors"][0];if(fault=="stats")a["stats"]["maxHp"]=999999;if(fault=="base")a["base"]["maxHp"]=999999;if(fault=="target")a["targetId"]="op_sable";if(fault=="instanceRevision")a["sources"][0]["instanceRevision"]=2;if(fault=="effectRevision")a["sources"][0]["effectRevision"]=2;if(fault=="tag")a["slots"][0]["setTag"]="SET01";if(fault=="phase")p["phase"]="COMMITTED";Rehash(p);Assert.Throws<ArgumentException>(()=>RunEquipmentStatSource.Read(p,original,(string)p["packetHash"],"a",(string)original["runId"],(string)original["originalContextHash"],1));}
  [TestCase("unique")][TestCase("enchantment")][TestCase("star3")][TestCase("star5")][TestCase("nullEffect")][TestCase("fourSlots")][TestCase("duplicate")][TestCase("virtualTag")][TestCase("effectStar")][TestCase("fraction")][TestCase("hpFloor")][TestCase("fullRuntime")][TestCase("version")][TestCase("phase")][TestCase("unknown")]
  public void TrustedDiagnosticMalformedContractsCannotWidenSupportedProducerRange(string fault){var p=Sample();var a=p["actors"][0];if(fault=="unique")((JArray)a["sources"][0]["snapshot"]["uniqueEffects"]).Add(new JObject{["effectId"]="EQ01"});if(fault=="enchantment")a["sources"][0]["snapshot"]["enchantment"]=new JObject();if(fault=="star3"||fault=="star5"){int star=fault=="star3"?3:5;a["slots"][0]["star"]=star;a["sources"][0]["snapshot"]["equipment"]["star"]=star;}if(fault=="nullEffect")a["sources"]=JValue.CreateNull();if(fault=="fourSlots")((JArray)a["slots"]).Add(JValue.CreateNull());if(fault=="duplicate")a["slots"][1]=a["slots"][0].DeepClone();if(fault=="virtualTag")a["slots"][0]["setTag"]=new JArray("SET01","SET04");if(fault=="effectStar")a["sources"][0]["snapshot"]["equipment"]["star"]=2;if(fault=="fraction")a["stats"]["attack"]["denominator"]="0";if(fault=="hpFloor")a["stats"]["maxHp"]=1625;if(fault=="fullRuntime")p["fullRuntimeSupported"]=true;if(fault=="version")p["version"]="old";if(fault=="phase")p["phase"]="COMMITTED";if(fault=="unknown")p["extra"]=1;Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p));}
  [Test] public void MissingAndUnsupportedOriginalProducerCasesSupplyNoNeutralSnapshot(){var data=Produced();Assert.AreEqual("equipment_stat_effect_handler_unavailable",(string)data["failures"][0]["errorCode"]);Assert.AreEqual("equipment_stat_effect_source_missing",(string)data["failures"][1]["errorCode"]);Assert.AreEqual(JTokenType.Null,data["failures"][0]["snapshot"].Type);Assert.AreEqual(JTokenType.Null,data["failures"][1]["snapshot"].Type);StringAssert.Contains("source_missing",Assert.Throws<ArgumentException>(()=>RunEquipmentStatSource.Read(null,null,null,"a","r",null,1)).Message);}
  [Test] public void OldProposalRestoresWithoutLookingUpChangedCurrentInventory(){var data=Produced();Assert.IsTrue((bool)data["originalSnapshotRestoredAfterCurrentRevisionChange"]);Assert.IsTrue((bool)data["healthUnchanged"]);var p=(JObject)data["twoStar"];Assert.IsTrue(JToken.DeepEquals(p,Read(p).Capture()));}
  [Test] public void ProposalCannotChangeExistingNativeHpAttackDefenseOrSnapshot(){var f=BNamedOperatorSourceTests.Native();var n=f.adapter.CreateRuntime(f.binding,BOrdinaryGeometryTests.Geometry(f.binding),10000);var before=n.Capture();var s=Read();StringAssert.Contains("not_committed",Assert.Throws<InvalidOperationException>(()=>s.RequireCommittedRuntimeSource()).Message);Assert.AreEqual(1400,n.Hp("op_kyle"));Assert.AreEqual(1600,n.Hp("op_sable"));Assert.IsTrue(JToken.DeepEquals(before,n.Capture()));Assert.IsFalse(s.CanApplyToNative);Assert.Throws<ArgumentException>(()=>s.ActorProposal("operator","op_sable"));File.WriteAllText(Qa+"native-proposal-not-applied.json",new JObject{["proposalHash"]=s.Hash,["phase"]=RunEquipmentStatSource.ProposedPhase,["proposedHp"]=1624,["nativeKyleHp"]=n.Hp("op_kyle"),["nativeSableHp"]=n.Hp("op_sable"),["inputHash"]=f.adapter.Input.OriginalHash,["nativeSnapshotUnchanged"]=JToken.DeepEquals(before,n.Capture()),["canApplyToNative"]=s.CanApplyToNative}.ToString());}
  [Test] public void CapacityAndMissingIndependentPinAreRejected(){var p=Sample();Assert.Throws<ArgumentException>(()=>RunEquipmentStatSource.Read(p,p,null,"a",(string)p["runId"],(string)p["originalContextHash"],1));p["oversized"]=new string('x',512*1024);StringAssert.Contains("capacity",Assert.Throws<ArgumentException>(()=>Read(p)).Message);}
 }
}
#endif
